WITH per_turn AS (SELECT trace_id, min(recorded_at) at, max(elapsed_ms) FILTER (WHERE stage='brain_first_token') token, max(elapsed_ms) FILTER (WHERE stage='tts_request') tts, max(elapsed_ms) FILTER (WHERE stage='first_voiced_audio_published') audio, max(elapsed_ms) FILTER (WHERE stage='brain_request') request, max(elapsed_ms) FILTER (WHERE stage='brain_complete') complete FROM voice_turn_timings WHERE recorded_at >= '2026-10-17T16:00:00Z' AND recorded_at < '2026-10-24T16:00:00Z' GROUP BY trace_id) SELECT count(*) turns, count(audio) audible, percentile_cont(ARRAY[0.5,0.9]) WITHIN GROUP (ORDER BY token) token_ms, percentile_cont(ARRAY[0.5,0.9]) WITHIN GROUP (ORDER BY tts) tts_ms, percentile_cont(ARRAY[0.5,0.9]) WITHIN GROUP (ORDER BY audio) audio_ms, percentile_cont(ARRAY[0.5,0.9]) WITHIN GROUP (ORDER BY token-request) brain_first_content_ms FROM per_turn WHERE audio IS NOT NULL;
